out={"title":"Flow pháp lý phát triển dự án BĐS — bản đầy đủ", "subtitle":"Khôi phục flow anh hướng dẫn: cổng lớn → thủ tục con → chi tiết điều kiện/hồ sơ/output/rủi ro/căn cứ. Dữ liệu lõi từ project_flow_v5: 33 node, 242 citations.", "version":"full-v5-restored", "nodes":v5['nodes'], "source_summaries":source_summaries}
(web/'bds_full_restored_flow.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
html=r'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flow pháp lý BĐS đầy đủ</title><style>
:root{--bg:#f4efe6;--paper:#fffaf2;--ink:#17211b;--muted:#657064;--line:#d6cab7;--green:#1f4e3b;--gold:#a87923;--red:#96392e;--blue:#234e74}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Inter,system-ui,Segoe UI,Arial}header{padding:26px clamp(18px,4vw,56px);background:#fbf7ef;border-bottom:1px solid var(--line)}h1{font-size:clamp(28px,4vw,52px);line-height:1.02;margin:0 0 8px;letter-spacing:-.045em}.sub{color:var(--muted);max-width:1100px;font-size:17px}.layout{display:grid;grid-template-columns:390px 1fr;gap:22px;padding:22px clamp(18px,4vw,56px)}aside{position:sticky;top:14px;align-self:start;max-height:calc(100vh - 28px);overflow:auto;border:1px solid var(--line);border-radius:18px;background:#fffaf5;padding:12px}.btn{display:block;width:100%;border:0;background:transparent;text-align:left;border-radius:10px;padding:9px 10px;cursor:pointer;color:var(--muted)}.btn:hover{background:#f0e8db}.btn.active{background:var(--green);color:white}.type-gate{font-weight:850;color:var(--ink)}.type-procedure{padding-left:24px}.type-decision,.type-detail{padding-left:44px;font-size:14px}.main{display:grid;gap:16px}.card{background:var(--paper);border:1px solid var(--line);border-radius:24px;padding:22px;box-shadow:0 12px 30px #0000000b}.crumb{font-size:12px;color:var(--gold);font-weight:800;text-transform:uppercase;letter-spacing:.08em}h2{font-size:clamp(24px,3vw,38px);line-height:1.08;margin:8px 0}.summary{font-size:18px;font-weight:650;margin:0 0 16px}.children{display:flex;gap:9px;flex-wrap:wrap}.chip{border:1px solid var(--line);border-radius:999px;background:white;color:var(--green);font-weight:700;padding:8px 11px;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.box{background:#fffdf8;border:1px solid var(--line);border-radius:16px;padding:14px}.box h3{margin:0 0 8px;font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--green)}.risk{border-color:#e3b9ae;background:#fff7f4}.risk h3{color:var(--red)}ul{margin:0;padding-left:18px}.basis{max-height:420px;overflow:auto}.quote{border-left:3px solid var(--gold);padding-left:10px;margin:10px 0;color:#343d36}.cite{display:inline-block;margin:4px 6px 0 0;padding:6px 9px;border:1px solid var(--line);border-radius:999px;background:white;font-size:12px;color:#354139}.docs{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}.doc{background:white;border:1px solid var(--line);border-radius:16px;padding:14px}.doc b{color:var(--blue)}.meta{color:var(--muted);font-size:13px}@media(max-width:980px){.layout{grid-template-columns:1fr}aside{position:relative;max-height:none}.grid{grid-template-columns:1fr}}</style></head><body><header><div class="crumb">Restored full flow / v5</div><h1 id="title"></h1><div class="sub" id="sub"></div></header><div class="layout"><aside id="nav"></aside><main class="main"><section class="card" id="detail"></section><section class="card"><div class="crumb">Tóm tắt văn bản nguồn</div><div class="docs" id="docs"></div></section></main></div><script>
let DATA,N={},active='root';fetch('bds_full_restored_flow.json').then(r=>r.json()).then(d=>{DATA=d;DATA.nodes.forEach(n=>N[n.id]=n);init()});
function init(){title.textContent=DATA.title;sub.textContent=DATA.subtitle;renderNav();renderDocs();show('root')}
function cls(n){return 'type-'+(n.type||'detail')}
function renderNav(){let root=N.root;let ids=[];function walk(id){ids.push(id);(N[id].children||[]).forEach(walk)} walk('root');nav.innerHTML=ids.map(id=>`<button id="b_${id}" class="btn ${cls(N[id])}" onclick="show('${id}')">${N[id].title}</button>`).join('')}
function path(id){let a=[];while(id){a.unshift(N[id].title);id=N[id].parent}return a.join(' / ')}
function list(title,arr,klass=''){return `<div class="box ${klass}"><h3>${title}</h3>${arr&&arr.length?`<ul>${arr.map(x=>`<li>${x}</li>`).join('')}</ul>`:'<p class=meta>Chưa có / không áp dụng ở node này.</p>'}</div>`}
function renderBasis(lb){if(!lb||!lb.length)return '<p class=meta>Chưa gắn căn cứ riêng cho node này.</p>';return lb.map(b=>`<div class=quote><b>${b.article||''}</b><div class=meta>${b.source_file||''}</div><div>${(b.summary||b.quote||'').slice(0,650)}${(b.summary||b.quote||'').length>650?'…':''}</div></div>`).join('')}
function show(id){active=id;document.querySelectorAll('.btn').forEach(b=>b.classList.remove('active'));let b=document.getElementById('b_'+id); if(b)b.classList.add('active');let n=N[id];let kids=n.children||[];detail.innerHTML=`<div class=crumb>${path(id)}</div><h2>${n.title}</h2><p class=summary>${n.summary||''}</p>${kids.length?`<div class=box><h3>Đầu mục bên trong</h3><div class=children>${kids.map(k=>`<button class=chip onclick="show('${k}')">${N[k].title}</button>`).join('')}</div></div>`:''}<div class=grid>${list('Việc nhà đầu tư cần chú ý',n.investment_focus)}${list('Output',n.outputs)}${list('Checkpoint / điều kiện',n.checkpoints)}${list('Rủi ro',n.risks,'risk')}</div><div class="box basis" style="margin-top:13px"><h3>Căn cứ và tóm tắt nội dung văn bản</h3>${renderBasis(n.legal_basis)}</div>`}
function renderDocs(){docs.innerHTML=DATA.source_summaries.map(d=>`<div class=doc><b>${d.doc}</b><p>${d.summary}</p>${d.basis.map(x=>`<span class=cite>${x}</span>`).join('')}</div>`).join('')}
</script></body></html>'''
(web/'bds_full_restored_flow.html').write_text(html,encoding='utf-8')
print('nodes',len(v5['nodes']),'citations',sum(len(n.get('legal_basis',[])) for n in v5['nodes']))
